__global__ void conv_transpose2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int groups
) {
