    int out_ch_idx = blockIdx.y;
    int out_h_idx = blockIdx.z;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || out_h_idx >= output_height) {
        return;
    }

    int group_size = out_channels / groups;
    int group_idx = out_ch_idx / group_size;

    // Calculate output width index
    int out_w_idx = threadIdx.x;

    if (out_w_idx >= output_width) {
        return;
    }

    // Initialize accumulator
    float acc = 0.0f;

    // Loop over input channels and kernel elements
    for (int ic = 0; ic < in_channels; ++ic) {
        int group_in_ch = ic % (in_channels / groups);
        int group_out_ch = out_ch_idx % group_size;

        if (group_in_ch != group_out_ch) continue;

        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                // Compute input coordinates
                int ih = out_h_idx * stride - padding + kh;
                int iw = out_w_idx * stride - padding + kw;

                // Check bounds
                if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                    // Calculate indices
                    int input_idx = batch_idx * (in_channels * input_height * input_width) +
                                   ic * (input_height * input_width) +
                                   ih * input_width + iw;

                    int weight_idx = out_ch_idx * (in_channels / groups * kernel_size * kernel_size) +
                                    ic * (kernel_size * kernel_size) +
                                    kh * kernel_size + kw;

                    // Accumulate
                    acc += __half2float(input[input_idx]) * __half2float(weight[weight_idx]);
                }
            }
        }
    }

    // Write result
    int output_idx = batch_idx * (out_channels * output_height * output_width) +
                    out_ch_idx * (output_height * output_width) +
                    out_h_idx * output_width + out_w_idx;

    output[output_idx] = __float2half(acc);
}

